package nz.ac.aut.pdc.supermarket.aftersale;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

import nz.ac.aut.pdc.supermarket.auth.Role;
import nz.ac.aut.pdc.supermarket.stock.Position;
import nz.ac.aut.pdc.supermarket.stock.StockChangeLine;
import nz.ac.aut.pdc.supermarket.stock.StockCheckResult;
import nz.ac.aut.pdc.supermarket.stock.StockOperations;
import nz.ac.aut.pdc.supermarket.stock.StockPorts;

/**
 * 售后编排骨架（WP-05）：资格校验 -> 额度视图/金额计算 -> 核销/替换候选
 * -> 替换品 IF-07 库存核对 -> 结算候选。不保存、不提交。
 *
 * <p>支持同一原行在一次命令内多条明细的顺序额度扣减；资格判定为简化规则：
 * 超 30 天或已开封非质量需要 CR07-09 店长/管理员例外；例外不改变数量/金额/库存校验。</p>
 */
public final class AftersaleService {

    private static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");
    private static final int RETURN_WINDOW_DAYS = 30;

    private final OriginalSaleReader originalSaleReader;
    private final QuotaLedgerReader quotaLedgerReader;
    private final ProductSnapshotReader productSnapshotReader;
    private final StockOperations stockOperations;
    private final QuotaViewBuilder quotaViewBuilder;
    private final QuotaCalculator quotaCalculator;
    private final QualityPairValidator qualityPairValidator;
    private final AftersaleAssembler assembler;
    private final StockPorts.IdGenerator idGenerator;
    private final SettlementCalculator settlementCalculator;

    public AftersaleService(
            OriginalSaleReader originalSaleReader,
            QuotaLedgerReader quotaLedgerReader,
            ProductSnapshotReader productSnapshotReader,
            StockOperations stockOperations,
            QuotaViewBuilder quotaViewBuilder,
            QuotaCalculator quotaCalculator,
            QualityPairValidator qualityPairValidator,
            AftersaleAssembler assembler,
            StockPorts.IdGenerator idGenerator,
            SettlementCalculator settlementCalculator) {
        this.originalSaleReader = Objects.requireNonNull(originalSaleReader, "originalSaleReader");
        this.quotaLedgerReader = Objects.requireNonNull(quotaLedgerReader, "quotaLedgerReader");
        this.productSnapshotReader = Objects.requireNonNull(productSnapshotReader, "productSnapshotReader");
        this.stockOperations = Objects.requireNonNull(stockOperations, "stockOperations");
        this.quotaViewBuilder = Objects.requireNonNull(quotaViewBuilder, "quotaViewBuilder");
        this.quotaCalculator = Objects.requireNonNull(quotaCalculator, "quotaCalculator");
        this.qualityPairValidator = Objects.requireNonNull(qualityPairValidator, "qualityPairValidator");
        this.assembler = Objects.requireNonNull(assembler, "assembler");
        this.idGenerator = Objects.requireNonNull(idGenerator, "idGenerator");
        this.settlementCalculator = Objects.requireNonNull(settlementCalculator, "settlementCalculator");
    }

    /** 兼容旧调用：默认结算计算器。 */
    public AftersaleService(
            OriginalSaleReader originalSaleReader,
            QuotaLedgerReader quotaLedgerReader,
            ProductSnapshotReader productSnapshotReader,
            StockOperations stockOperations,
            QuotaViewBuilder quotaViewBuilder,
            QuotaCalculator quotaCalculator,
            QualityPairValidator qualityPairValidator,
            AftersaleAssembler assembler,
            StockPorts.IdGenerator idGenerator) {
        this(originalSaleReader, quotaLedgerReader, productSnapshotReader, stockOperations,
                quotaViewBuilder, quotaCalculator, qualityPairValidator, assembler, idGenerator,
                new SettlementCalculator());
    }

    public AftersaleResult apply(
            StockPorts.WorkingCopyView workingCopy, AftersaleCommand command, Role actorRole) {
        Objects.requireNonNull(workingCopy, "workingCopy");
        Objects.requireNonNull(command, "command");
        try {
            Instant now = idGenerator.now();
            String aftersaleId = idGenerator.nextId("AF");
            List<Redemption> redemptions = new ArrayList<>();
            List<Replacement> replacements = new ArrayList<>();
            List<AftersaleResult.StockEntryView> stockViews = new ArrayList<>();
            List<Settlement> settlements = new ArrayList<>();
            List<nz.ac.aut.pdc.supermarket.stock.StockEntry> stockOverlay = new ArrayList<>();
            Map<String, List<Redemption>> pendingByLine = new HashMap<>();

            for (AftersaleCommandLine line : command.lines()) {
                Optional<OriginalSaleLine> originalOptional = originalSaleReader.readLine(line.saleLineId());
                if (originalOptional.isEmpty()) {
                    return new AftersaleResult.Rejected(
                            "REFERENCE_INVALID", "saleLineId", "原销售行不存在：" + line.saleLineId());
                }
                OriginalSaleLine original = originalOptional.get();

                boolean exceptionRequired = requiresException(original, line, now);
                Optional<AftersaleResult.Rejected> eligibility =
                        checkEligibility(command, actorRole, exceptionRequired);
                if (eligibility.isPresent()) {
                    return eligibility.get();
                }

                List<Redemption> history = new ArrayList<>(
                        quotaLedgerReader.effectiveFor(original.saleLineId()));
                history.addAll(pendingByLine.getOrDefault(original.saleLineId(), List.of()));
                QuotaView view = quotaViewBuilder.build(original, history);
                if (line.quantity() > view.remainingQty()) {
                    return new AftersaleResult.Rejected(
                            "INVALID_INPUT", "quantity", "本次数量超过原行剩余额度");
                }
                boolean settlesRemaining = line.quantity() == view.remainingQty();
                BigDecimal amount = quotaCalculator.allocate(
                        line.quantity(), view, new SettlementContext(settlesRemaining));
                Redemption redemption = assembler.assembleRedemption(
                        aftersaleId,
                        command.requestKey(),
                        original,
                        line,
                        amount,
                        exceptionRequired ? command.exceptionAuthorizedBy() : null,
                        exceptionRequired ? command.exceptionReason() : null,
                        exceptionRequired ? command.relaxedRule() : null);
                redemptions.add(redemption);
                pendingByLine.computeIfAbsent(original.saleLineId(), key -> new ArrayList<>())
                        .add(redemption);

                Replacement replacement = null;
                if (line.kind() == RedemptionKind.EXCHANGE) {
                    Optional<ProductSnapshot> productOptional =
                            productSnapshotReader.find(line.replacementBarcode());
                    if (productOptional.isEmpty()) {
                        return new AftersaleResult.Rejected(
                                "REFERENCE_INVALID", "replacementBarcode", "替换品不存在");
                    }
                    ProductSnapshot product = productOptional.get();
                    BigDecimal replacementAmount = product.unitPrice()
                            .multiply(BigDecimal.valueOf(line.replacementQty()));
                    replacement = assembler.assembleReplacement(
                            aftersaleId, original, line, redemption, product, replacementAmount);
                    if (line.qualityPair()) {
                        Optional<String> pairRejection =
                                qualityPairValidator.validate(original, redemption, replacement);
                        if (pairRejection.isPresent()) {
                            return new AftersaleResult.Rejected(
                                    "INVALID_INPUT", "qualityPair", pairRejection.get());
                        }
                    }
                    replacements.add(replacement);

                    StockChangeLine stockChange = new StockChangeLine(
                            line.replacementBarcode(),
                            Position.S,
                            -line.replacementQty(),
                            redemption.redemptionId(),
                            null,
                            null,
                            "EV-AF-" + replacement.lineId(),
                            null);
                    StockCheckResult stockResult =
                            stockOperations.check(workingCopy, stockOverlay, List.of(stockChange));
                    if (stockResult instanceof StockCheckResult.Rejected rejected) {
                        return new AftersaleResult.Rejected(
                                rejected.code(), rejected.field(), rejected.message());
                    }
                    if (stockResult instanceof StockCheckResult.Failed failed) {
                        return new AftersaleResult.Failed(failed.code(), failed.message());
                    }
                    StockCheckResult.Prepared prepared = (StockCheckResult.Prepared) stockResult;
                    stockOverlay.addAll(prepared.entries());
                    for (var entry : prepared.entries()) {
                        stockViews.add(new AftersaleResult.StockEntryView(
                                entry.id(), entry.barcode(), entry.position(), entry.delta(),
                                entry.eventKey(), entry.transferKey()));
                    }
                }
                settlements.add(settlementCalculator.calculate(redemption, replacement));
            }
            return new AftersaleResult.Prepared(redemptions, replacements, stockViews, settlements);
        } catch (RuntimeException ex) {
            return new AftersaleResult.Failed("AFTERSALE_FAILED", "售后处理暂时不可用");
        }
    }

    private Optional<AftersaleResult.Rejected> checkEligibility(
            AftersaleCommand command, Role actorRole, boolean exceptionRequired) {
        if (!exceptionRequired) {
            return Optional.empty();
        }
        if (actorRole == null || !actorRole.canAuthorizeException()) {
            return Optional.of(new AftersaleResult.Rejected(
                    "FORBIDDEN", "actorRole", "该售后需要店长/管理员授权例外"));
        }
        if (isBlank(command.exceptionAuthorizedBy())
                || isBlank(command.exceptionReason())
                || isBlank(command.relaxedRule())) {
            return Optional.of(new AftersaleResult.Rejected(
                    "INVALID_INPUT", "exception",
                    "资格例外必须记录授权人、原因和所放宽规则"));
        }
        return Optional.empty();
    }

    private boolean requiresException(OriginalSaleLine original, AftersaleCommandLine line, Instant now) {
        LocalDate saleDate = original.saleTime().atZone(ZONE).toLocalDate();
        boolean withinWindow = !now.atZone(ZONE).toLocalDate().isAfter(saleDate.plusDays(RETURN_WINDOW_DAYS));
        boolean openedNonQuality = line.opened() && !line.qualityProblem();
        return !(withinWindow && !openedNonQuality);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
package nz.ac.aut.pdc.supermarket.reversal;

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import java.util.Optional;

import nz.ac.aut.pdc.supermarket.aftersale.Effect;
import nz.ac.aut.pdc.supermarket.aftersale.Redemption;
import nz.ac.aut.pdc.supermarket.auth.Role;
import nz.ac.aut.pdc.supermarket.stock.StockChangeLine;
import nz.ac.aut.pdc.supermarket.stock.StockCheckResult;
import nz.ac.aut.pdc.supermarket.stock.StockEntry;
import nz.ac.aut.pdc.supermarket.stock.StockOperations;
import nz.ac.aut.pdc.supermarket.stock.StockPorts;

/**
 * 冲销编排骨架（WP-06）：高权限校验 → D1 依赖/重复冲销检查 → 生成 RELEASE
 * 核销与反向库存候选。不保存、不提交。
 *
 * <p>D1：若存在引用原核销的后续记录，则拒绝直接冲销；本骨架只做只读检查，
 * 不自动级联重建。B 新增业务码 `DEPENDENCY_BLOCKED`/`REVERSAL_FAILED` 需通知 A 登记。</p>
 */
public final class ReversalService {

    private final RedemptionReader redemptionReader;
    private final ReversalDependencyReader dependencyReader;
    private final StockEffectReader stockEffectReader;
    private final StockOperations stockOperations;
    private final StockPorts.IdGenerator idGenerator;

    public ReversalService(
            RedemptionReader redemptionReader,
            ReversalDependencyReader dependencyReader,
            StockEffectReader stockEffectReader,
            StockOperations stockOperations,
            StockPorts.IdGenerator idGenerator) {
        this.redemptionReader = Objects.requireNonNull(redemptionReader, "redemptionReader");
        this.dependencyReader = Objects.requireNonNull(dependencyReader, "dependencyReader");
        this.stockEffectReader = Objects.requireNonNull(stockEffectReader, "stockEffectReader");
        this.stockOperations = Objects.requireNonNull(stockOperations, "stockOperations");
        this.idGenerator = Objects.requireNonNull(idGenerator, "idGenerator");
    }

    public ReversalResult reverse(
            StockPorts.WorkingCopyView workingCopy, ReversalCommand command, Role actorRole) {
        Objects.requireNonNull(workingCopy, "workingCopy");
        Objects.requireNonNull(command, "command");
        if (actorRole != Role.MANAGER && actorRole != Role.ADMIN) {
            return new ReversalResult.Rejected(
                    "FORBIDDEN", "actorRole", "冲销需要店长或管理员权限");
        }
        try {
            Optional<Redemption> originalOptional = redemptionReader.find(command.redemptionId());
            if (originalOptional.isEmpty()) {
                return new ReversalResult.Rejected(
                        "REFERENCE_INVALID", "redemptionId", "原核销不存在");
            }
            Redemption original = originalOptional.get();
            if (original.effect() == Effect.RELEASE) {
                return new ReversalResult.Rejected(
                        "INVALID_INPUT", "redemptionId", "RELEASE 记录不能再次冲销");
            }
            if (redemptionReader.findReversalOf(original.redemptionId()).isPresent()) {
                return new ReversalResult.Rejected(
                        "EVENT_CONFLICT", "redemptionId", "该核销已有有效冲销记录");
            }
            List<String> dependents = dependencyReader.dependentRecordIds(original.redemptionId());
            if (dependents != null && !dependents.isEmpty()) {
                return new ReversalResult.Rejected(
                        "DEPENDENCY_BLOCKED", "redemptionId",
                        "存在引用该核销的后续记录，不能直接冲销：" + String.join(",", dependents));
            }
            List<StockEntry> effects = stockEffectReader.entriesFor(original.redemptionId());
            if (effects == null || effects.isEmpty()) {
                return new ReversalResult.Rejected(
                        "REFERENCE_INVALID", "stockEffect", "原核销没有可冲销的库存流水");
            }

            Redemption release = new Redemption(
                    idGenerator.nextId("REV-RED"),
                    original.sourceLineId(),
                    original.originalSaleLineId(),
                    original.originalBarcode(),
                    original.aftersaleId(),
                    original.kind(),
                    Effect.RELEASE,
                    original.quantity(),
                    original.amount(),
                    command.requestKey(),
                    original.redemptionId(),
                    original.opened(),
                    original.qualityProblem());

            List<StockChangeLine> changes = new ArrayList<>(effects.size());
            for (StockEntry effect : effects) {
                changes.add(new StockChangeLine(
                        effect.barcode(),
                        effect.position(),
                        -effect.delta(),
                        original.redemptionId(),
                        effect.transferKey(),
                        effect.id(),
                        "REV-" + effect.eventKey(),
                        effect.receiptReviewId()));
            }
            StockCheckResult checked = stockOperations.check(workingCopy, List.of(), changes);
            if (checked instanceof StockCheckResult.Rejected rejected) {
                return new ReversalResult.Rejected(
                        rejected.code(), rejected.field(), rejected.message());
            }
            if (checked instanceof StockCheckResult.Failed failed) {
                return new ReversalResult.Failed(failed.code(), failed.message());
            }
            StockCheckResult.Prepared prepared = (StockCheckResult.Prepared) checked;
            return new ReversalResult.Prepared(
                    new ReversalPlan(original.redemptionId(), release, prepared.entries()));
        } catch (RuntimeException ex) {
            return new ReversalResult.Failed("REVERSAL_FAILED", "冲销处理暂时不可用");
        }
    }
}
package nz.ac.aut.pdc.supermarket.stock;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/**
 * IF-07 的骨架实现：读取余额、校验变动、生成候选流水。
 *
 * <p>职责：编排只读读取 + 纯规则校验 + 候选组装；不保存、不分配 commitOrdinal、
 * 不调用提交入口。依赖全部通过构造器注入，便于替换为 A 的真实实现。</p>
 */
public final class StockService implements StockOperations {

    private final StockPorts.ProductCatalog productCatalog;
    private final StockPorts.IdGenerator idGenerator;
    private final StockValidator validator;

    public StockService(
            StockPorts.ProductCatalog productCatalog,
            StockPorts.IdGenerator idGenerator,
            StockValidator validator) {
        this.productCatalog = Objects.requireNonNull(productCatalog, "productCatalog");
        this.idGenerator = Objects.requireNonNull(idGenerator, "idGenerator");
        this.validator = Objects.requireNonNull(validator, "validator");
    }

    @Override
    public List<StockBalance> balances(
            StockPorts.WorkingCopyView workingCopy, Collection<String> barcodes) {
        Objects.requireNonNull(workingCopy, "workingCopy");
        Objects.requireNonNull(barcodes, "barcodes");
        return workingCopy.balances(barcodes).stream()
                .sorted(Comparator.comparing(StockBalance::barcode)
                        .thenComparing(StockBalance::position))
                .toList();
    }

    @Override
    public StockCheckResult check(
            StockPorts.WorkingCopyView workingCopy,
            List<StockEntry> overlayEntries,
            List<StockChangeLine> changes) {
        Objects.requireNonNull(workingCopy, "workingCopy");
        Objects.requireNonNull(overlayEntries, "overlayEntries");
        if (changes == null) {
            return new StockCheckResult.Rejected("INVALID_INPUT", "lines", "变动组不能为空");
        }
        try {
            List<StockChangeLine> requestLines = List.copyOf(changes);
            Optional<StockCheckResult.Rejected> referenceRejection = validateReferences(requestLines);
            if (referenceRejection.isPresent()) {
                return referenceRejection.get();
            }

            Map<StockValidator.BalanceKey, Integer> balancesBefore = balancesBefore(workingCopy, overlayEntries, requestLines);
            Optional<StockValidator.StockRejection> violation = validator.validate(requestLines, balancesBefore);
            if (violation.isPresent()) {
                StockValidator.StockRejection rejection = violation.get();
                return new StockCheckResult.Rejected(rejection.code(), rejection.field(), rejection.message());
            }

            List<StockEntry> prepared = new ArrayList<>(requestLines.size());
            for (StockChangeLine line : requestLines) {
                String eventKey = line.eventKey() == null || line.eventKey().isBlank()
                        ? idGenerator.nextId("EV")
                        : line.eventKey();
                prepared.add(new StockEntry(
                        idGenerator.nextId("SE"),
                        line.barcode(),
                        line.position(),
                        line.delta(),
                        eventKey,
                        line.transferKey(),
                        line.sourceLineId(),
                        line.reverseOfId(),
                        line.receiptReviewId()));
            }
            return new StockCheckResult.Prepared(prepared, balancesAfter(balancesBefore, requestLines));
        } catch (RuntimeException ex) {
            return new StockCheckResult.Failed("STOCK_CHECK_FAILED", "库存核对暂时不可用");
        }
    }

    private Optional<StockCheckResult.Rejected> validateReferences(List<StockChangeLine> changes) {
        for (StockChangeLine line : changes) {
            if (productCatalog.productName(line.barcode()).isEmpty()) {
                return Optional.of(new StockCheckResult.Rejected(
                        "REFERENCE_INVALID", line.barcode(), "商品不存在：" + line.barcode()));
            }
        }
        return Optional.empty();
    }

    private Map<StockValidator.BalanceKey, Integer> balancesBefore(
            StockPorts.WorkingCopyView workingCopy,
            List<StockEntry> overlayEntries,
            List<StockChangeLine> changes) {
        List<String> barcodes = changes.stream().map(StockChangeLine::barcode).distinct().toList();
        Map<StockValidator.BalanceKey, Integer> balances = new HashMap<>();
        for (StockBalance balance : workingCopy.balances(barcodes)) {
            balances.put(new StockValidator.BalanceKey(balance.barcode(), balance.position()), balance.quantity());
        }
        for (StockEntry entry : overlayEntries) {
            StockValidator.BalanceKey key = new StockValidator.BalanceKey(entry.barcode(), entry.position());
            balances.merge(key, entry.delta(), Integer::sum);
        }
        return balances;
    }

    private List<StockBalance> balancesAfter(
            Map<StockValidator.BalanceKey, Integer> balancesBefore,
            List<StockChangeLine> changes) {
        Map<StockValidator.BalanceKey, Integer> after = new HashMap<>(balancesBefore);
        for (StockChangeLine line : changes) {
            StockValidator.BalanceKey key = new StockValidator.BalanceKey(line.barcode(), line.position());
            after.merge(key, line.delta(), Integer::sum);
        }
        return after.entrySet().stream()
                .sorted(Map.Entry.comparingByKey(
                        Comparator.comparing(StockValidator.BalanceKey::barcode)
                                .thenComparing(StockValidator.BalanceKey::position)))
                .map(entry -> new StockBalance(
                        entry.getKey().barcode(), entry.getKey().position(), entry.getValue()))
                .toList();
    }
}
package nz.ac.aut.pdc.supermarket.stock;

import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * IF-07 的纯规则校验器：数量边界、位置、补货双腿守恒、来源位置非负。
 *
 * <p>只做规则判断，不读外部数据、不保存；工作副本余额由调用方传入，
 * 便于用虚构夹具做边界单测。</p>
 */
public final class StockValidator {

    public static final int MIN_QUANTITY = 1;
    public static final int MAX_QUANTITY = 9999;

    /**
     * @param changes        本次完整变动组
     * @param balancesBefore 调用前各（商品, 位置）余额；缺失按 0 处理
     * @return 第一条拒绝原因；全部通过返回 empty
     */
    public Optional<StockRejection> validate(
            List<StockChangeLine> changes, Map<BalanceKey, Integer> balancesBefore) {

        if (changes == null || changes.isEmpty()) {
            return Optional.of(new StockRejection("INVALID_INPUT", "lines", "变动组不能为空"));
        }

        for (StockChangeLine line : changes) {
            if (line == null || line.barcode().isBlank()) {
                return Optional.of(new StockRejection("INVALID_INPUT", "barcode", "商品条码不能为空"));
            }
            int quantity = Math.abs(line.delta());
            if (quantity < MIN_QUANTITY || quantity > MAX_QUANTITY) {
                return Optional.of(new StockRejection(
                        "INVALID_INPUT", "quantity", "业务数量必须为 1–9999 的整数"));
            }
        }

        Optional<StockRejection> transferRejection = validateTransfers(changes);
        if (transferRejection.isPresent()) {
            return transferRejection;
        }

        Map<BalanceKey, Integer> netDeltas = new HashMap<>();
        for (StockChangeLine line : changes) {
            BalanceKey key = new BalanceKey(line.barcode(), line.position());
            netDeltas.merge(key, line.delta(), Integer::sum);
        }

        for (Map.Entry<BalanceKey, Integer> entry : netDeltas.entrySet().stream()
                .sorted(Comparator.comparing(e -> e.getKey().barcode() + ":" + e.getKey().position()))
                .toList()) {
            if (entry.getValue() >= 0) {
                continue;
            }
            BalanceKey key = entry.getKey();
            int available = balancesBefore.getOrDefault(key, 0);
            if (available + entry.getValue() < 0) {
                return Optional.of(new StockRejection(
                        "INSUFFICIENT_STOCK",
                        key.barcode() + ":" + key.position(),
                        "来源位置库存不足：可用 " + available + "，本次需要 " + (-entry.getValue())));
            }
        }
        return Optional.empty();
    }

    private Optional<StockRejection> validateTransfers(List<StockChangeLine> changes) {
        Map<String, List<StockChangeLine>> groups = changes.stream()
                .filter(line -> line.transferKey() != null && !line.transferKey().isBlank())
                .collect(java.util.stream.Collectors.groupingBy(StockChangeLine::transferKey));

        for (Map.Entry<String, List<StockChangeLine>> group : groups.entrySet()) {
            List<StockChangeLine> lines = group.getValue();
            if (lines.size() != 2) {
                return Optional.of(unbalanced(group.getKey(), "转移必须恰好由两条流水组成"));
            }
            StockChangeLine first = lines.get(0);
            StockChangeLine second = lines.get(1);
            boolean sameBarcode = first.barcode().equals(second.barcode());
            boolean oppositePositions = first.position() != second.position();
            boolean sumsToZero = first.delta() + second.delta() == 0;
            if (!sameBarcode || !oppositePositions || !sumsToZero) {
                return Optional.of(unbalanced(group.getKey(), "转移两腿必须同商品、异位置且数量互为相反数"));
            }
        }
        return Optional.empty();
    }

    private StockRejection unbalanced(String transferKey, String message) {
        return new StockRejection("TRANSFER_UNBALANCED", transferKey, message);
    }

    /** 校验器使用的（商品, 位置）键。 */
    public record BalanceKey(String barcode, Position position) {
        public BalanceKey {
            if (barcode == null || barcode.isBlank()) {
                throw new IllegalArgumentException("barcode must not be blank");
            }
            if (position == null) {
                throw new IllegalArgumentException("position must not be null");
            }
        }
    }

    /** 校验拒绝原因；code 使用共享规范 §4 的稳定错误码。 */
    public record StockRejection(String code, String field, String message) {
    }
}

