        LossRecord lossRecord = new LossRecord(
                idGenerator.nextId("LOSS"),
                null,
                barcode,
                position,
                quantity,
                LossOrigin.STORE,
                null,
                LossState.PENDING);
        return new LossResult.Prepared(lossRecord, prepared.entries(), prepared.balancesAfter());
    }
